def field_html(name,typ,help):
    label=name
    mandatory='*' in name and '#' not in name
    auto='#' in name
    clean=name.replace(' *','').replace(' ~','').replace(' #','')
    cls='field'
    attr=''
    if 'PAN' in clean and clean in ('PAN','SignatoryPAN'): attr=' data-regex="^[A-Za-z]{5}[0-9]{4}[A-Za-z]$" data-message="PAN must match AAAAA9999A"'
    if clean in ('MobileNo','AlternateMobile','SignatoryMobile','WhatsAppNo') or 'Mobile' in clean: attr=' data-regex="^[6-9][0-9]{9}$" data-message="Enter a valid 10 digit Indian mobile number"'
    if clean=='Pincode': attr=' data-regex="^[1-9][0-9]{5}$" data-message="Pincode must be 6 digits"'
    if clean=='IFSC': attr=' data-regex="^[A-Za-z]{4}0[A-Za-z0-9]{6}$" data-message="Enter a valid IFSC"'
    if typ=='Textarea': inp=f'<textarea name="{clean}"{attr}></textarea>'
    elif typ=='Select': inp='<select name="%s"><option value="">Select…</option><option>Configured master</option><option>Active</option><option>Inactive</option><option>Yes</option><option>No</option></select>'%clean
    elif typ=='Yes/No': inp='<select name="%s"><option value="">Select…</option><option>Yes</option><option>No</option></select>'%clean
    elif typ=='File': inp=f'<input type="file" name="{clean}" accept=".pdf,.png,.jpg,.jpeg,.svg">'
    elif typ=='Date': inp=f'<input type="date" name="{clean}">'
    elif typ=='DateTime': inp=f'<input type="datetime-local" name="{clean}">'
    elif typ=='Time': inp=f'<input type="time" name="{clean}">'
    elif typ=='Number': inp=f'<input type="number" name="{clean}" min="0" step="0.01">'
    elif typ=='Email': inp=f'<input type="email" name="{clean}">'
    elif typ=='URL': inp=f'<input type="url" name="{clean}" placeholder="https://">'
    elif typ=='Password': inp=f'<input type="password" name="{clean}">'
    else: inp=f'<input type="text" name="{clean}"{attr}>'
    mark='<span class="req">*</span>' if mandatory else ('<span class="auto">#</span>' if auto else '<span class="optional">optional</span>')
    return f'<div class="field"><label>{clean} {mark}</label>{inp}<div class="hint">{help}</div></div>'

